-- The SET clauses that make an identity column's sequence match the options its package declares, or '' when they
-- already do. Only the options written in the declaration are compared: a bare GENERATED ... AS IDENTITY leaves the
-- sequence as it is, as it always has. p_Generated is the declared text, e.g.
-- GENERATED BY DEFAULT AS IDENTITY(START WITH 10 INCREMENT BY 2 MINVALUE 5 MAXVALUE 1000 CACHE 20 CYCLE).
-- A column not there under that name (WhatIf has not added or renamed it) has no sequence to compare, so it reads '',
-- because a caller cannot keep PostgreSQL from evaluating this before the join that would have skipped the column.
CREATE OR REPLACE FUNCTION "SchemaSmith"."IdentityOptionChanges"(p_Generated TEXT, p_Schema TEXT, p_Table TEXT, p_Column TEXT) RETURNS TEXT
    LANGUAGE plpgsql STABLE
AS $$
DECLARE
  v_opts TEXT := UPPER(COALESCE(SUBSTRING(p_Generated FROM '\((.*)\)\s*$'), ''));
  v_rel REGCLASS;
  v_seq pg_catalog.pg_sequence%ROWTYPE;
  v_val TEXT;
  v_out TEXT := '';
BEGIN
  IF v_opts = '' THEN RETURN ''; END IF;
  v_rel := to_regclass(QUOTE_IDENT(p_Schema) || '.' || QUOTE_IDENT(p_Table));
  IF v_rel IS NULL OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
                                   WHERE attrelid = v_rel AND attname = p_Column AND attnum > 0 AND NOT attisdropped) THEN
    RETURN '';
  END IF;
  SELECT * INTO v_seq FROM pg_catalog.pg_sequence WHERE seqrelid = pg_get_serial_sequence(v_rel::TEXT, p_Column)::REGCLASS;
  IF NOT FOUND THEN RETURN ''; END IF;

  v_val := SUBSTRING(v_opts FROM 'START\s+(?:WITH\s+)?(-?\d+)');
  IF v_val IS NOT NULL AND v_val::BIGINT <> v_seq.seqstart THEN v_out := v_out || ' SET START WITH ' || v_val; END IF;
  v_val := SUBSTRING(v_opts FROM 'INCREMENT\s+(?:BY\s+)?(-?\d+)');
  IF v_val IS NOT NULL AND v_val::BIGINT <> v_seq.seqincrement THEN v_out := v_out || ' SET INCREMENT BY ' || v_val; END IF;
  v_val := SUBSTRING(v_opts FROM '(?<!NO\s)MINVALUE\s+(-?\d+)');
  IF v_val IS NOT NULL AND v_val::BIGINT <> v_seq.seqmin THEN v_out := v_out || ' SET MINVALUE ' || v_val; END IF;
  v_val := SUBSTRING(v_opts FROM '(?<!NO\s)MAXVALUE\s+(-?\d+)');
  IF v_val IS NOT NULL AND v_val::BIGINT <> v_seq.seqmax THEN v_out := v_out || ' SET MAXVALUE ' || v_val; END IF;
  v_val := SUBSTRING(v_opts FROM 'CACHE\s+(\d+)');
  IF v_val IS NOT NULL AND v_val::BIGINT <> v_seq.seqcache THEN v_out := v_out || ' SET CACHE ' || v_val; END IF;
  IF v_opts ~ '(^|\s)NO\s+CYCLE(\s|$)' THEN
    IF v_seq.seqcycle THEN v_out := v_out || ' SET NO CYCLE'; END IF;
  ELSIF v_opts ~ '(^|\s)CYCLE(\s|$)' AND NOT v_seq.seqcycle THEN
    v_out := v_out || ' SET CYCLE';
  END IF;
  RETURN v_out;
END;
$$;
